const TWS_CHANNEL = 'UC9VKHMUGg5gqSebXW1m5GBw';
const HITPOINT_CHANNEL = 'UCyFDhiqKcVqoIGB3CmJJFUg';
const data = $input.first().json;
const channelId = data.channel_id || '';

let voice;
let channelSlug;
if (channelId === HITPOINT_CHANNEL) {
  channelSlug = 'hitpoint';
  voice = {
    perspective: 'team',
    brand: 'Hitpoint Live',
    primary_name: 'Fahad',
    pronoun: 'we',
    tone: 'Team analysis voice. Use "we" and "our team" throughout. Reference Fahad by name when attributing specific market calls or analysis. The team discovered, the team spotted.',
    cta: 'Join the Hitpoint community for live market coverage and real-time trade alerts.'
  };
} else {
  channelSlug = 'tws';
  voice = {
    perspective: 'first_person',
    brand: 'Trading With Sidhant',
    primary_name: 'Sidhant',
    pronoun: 'I',
    tone: 'First person as Sidhant, the Philosopher-Operator: a systems-building CEO who trades, codes and thinks in first principles. Modern philosopher, tech-forward, entertaining as hell. Direct, opinionated, personal. Use "I" naturally. Reason from first principles and show the system behind the thinking. Depth, not tips, not signals, not guru shortcuts. Punch up at gurus, at hype and at the system that sells shortcuts; never punch down at the reader. No lifestyle flexing, no income or luxury signalling. No lecture register: you are thinking out loud with a sharp peer, not teaching a class. Not a trading educator, not a finance guru.',
    cta: 'Catch me live on the next TWS stream, that is where the system gets built in the open.'
  };
}

return [{ json: { ...data, voice, channelSlug } }];

