    try {
      const v = fn();
      return (v === undefined || v === null) ? fallback : v;
    } catch (e) { return fallback; }
  }
  function shapeText(j) {
    if (!j) { return ''; }
    if (typeof j.output === 'string') { return j.output; }
    if (j.output && j.output[0] && j.output[0].content && j.output[0].content[0]) { return j.output[0].content[0].text || ''; }
    if (j.content && Array.isArray(j.content) && j.content[0]) { return j.content[0].text || ''; }
    if (typeof j.text === 'string') { return j.text; }
    return '';
  }
  const voice = safeGet(function() { return $('Voice Router').first().json.voice; }, {});
  let mining = safeGet(function() { return shapeText($json); }, '');
  if (!mining || !mining.trim()) { mining = safeGet(function() { return shapeText($('Phase 1: Deep Transcript Mining').first().json); }, ''); }
  if (!mining || !mining.trim()) {
    return 'TRANSCRIPT MINING DATA UNAVAILABLE. The upstream mining step returned no usable output, so there is nothing to build a blueprint from. Do not invent transcript content, quotes, price levels or market data. Reply with exactly this JSON and nothing else: {"error":"no_mining_data","primary_keyword":"","secondary_keywords":[],"search_intent":"informational","title":"","slug":"","hook":"","seo_description":"","category":"market-recap","tags":[],"market_scope":"mixed","market_data_age_days":0,"hero_image_prompt":"","hero_image_alt":"","faq_plan":[],"section_plan":[]}';
  }
