={{ (function() {
  const fallback = { query: 'indian stock market nifty bank nifty analysis', search_depth: 'advanced', max_results: 6, include_answer: true };
  try {
    const rawText = String($json.output[0].content[0].text || '');
    const stripped = rawText.replace(/```[a-zA-Z0-9_-]*/g, '').trim();
    const s = stripped.indexOf('{');
    const e = stripped.lastIndexOf('}');
    const seo = JSON.parse(s !== -1 && e > s ? stripped.slice(s, e + 1) : stripped);
    const pk = String(seo.primary_keyword || '').trim();
    const musts = [];
    (Array.isArray(seo.section_plan) ? seo.section_plan : []).forEach(function(sec) {
      const list = (sec && Array.isArray(sec.must_include)) ? sec.must_include : [];
      list.forEach(function(m) { const t = String(m === null || m === undefined ? '' : m).trim(); if (t) { musts.push(t); } });
    });
    const score = function(t) { return (/[0-9]/.test(t) ? 10000 : 0) + Math.min(t.length, 200); };
    musts.sort(function(a, b) { return score(b) - score(a); });
    const query = [pk].concat(musts.slice(0, 2)).filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
    if (!query) { return JSON.stringify(fallback); }
    const body = { query: query.slice(0, 380), search_depth: 'advanced', max_results: 6, include_answer: true };
    const scope = String(seo.market_scope || '').trim().toLowerCase();
    const cat = String(seo.category || '').trim().toLowerCase();
    if (scope !== 'education' && cat !== 'education') { body.topic = 'news'; body.time_range = 'month'; }
    return JSON.stringify(body);
  } catch (err) { return JSON.stringify(fallback); }
})() }}

