// Assemble final publish payload from all pipeline phases
const triggerData = $('Workflow Trigger').first().json;
const videoId = triggerData.video_id;
const chartUrls = triggerData.chart_urls || [];
const voiceData = $('Voice Router').first().json;
const channelSlug = voiceData.channelSlug || 'tws';

// ---- contract v2 constants ----
const BLOG_BASE = 'https://blogs.twsgurukulx.com';
const POST_PREFIX = BLOG_BASE + '/posts/';
const WORDS_PER_MINUTE = 220;
const AUTHOR = {
  name: 'Sidhant',
  role: 'Founder, TWSGurukulX',
  url: 'https://blogs.twsgurukulx.com/about',
  sameAs: [
    'https://youtube.com/@tradingwithsidhant',
    'https://instagram.com/tradingwithsidhant',
    'https://x.com/tradingwsidhant',
    'https://t.me/tradingwsidhant',
    'https://twsgurukul.com'
  ]
};

// Robust JSON extraction: strip code fences, then take the substring from the
// FIRST { to the LAST }. Survives LLMs that emit prose before/after the JSON.
function safeParse(str, fallback) {
  const raw = (str === null || str === undefined) ? '' : String(str);
  const stripped = raw.replace(/```[a-zA-Z0-9_-]*/g, '').trim();
  const first = stripped.indexOf('{');
  const last = stripped.lastIndexOf('}');
  const candidate = (first !== -1 && last > first) ? stripped.slice(first, last + 1) : stripped;
  try { return JSON.parse(candidate); } catch (e) {
    try { return JSON.parse(stripped); } catch (e2) {
      try { return JSON.parse(raw.trim()); } catch (e3) { return fallback; }
    }
  }
}

function fixMojibake(text) {
  if (!text || typeof text !== 'string') return text;
  return text
    .replace(/â€”/g, '—')
    .replace(/â€“/g, '–')
    .replace(/â€™/g, '’')
    .replace(/â€˜/g, '‘')
    .replace(/â€œ/g, '“')
    .replace(/â€[]/g, '”')
    .replace(/â€¦/g, '…')
    .replace(/Â«/g, '«')
    .replace(/Â»/g, '»')
    .replace(/Ã©/g, 'é')
    .replace(/Ã¨/g, 'è');
}

// TITLES / HEADINGS: an em-dash becomes a colon, never a comma splice.
function cleanTitle(text) {
  if (!text || typeof text !== 'string') return text;
  return text
    .replace(/\s*—\s*/g, ': ')
    .replace(/(?::\s*){2,}/g, ': ')
    .replace(/,\s*:\s*/g, ': ')
    .replace(/:\s*,\s*/g, ': ')
    .replace(/\s+:/g, ':')
    .replace(/ {2,}/g, ' ')
    .replace(/^[\s:,]+/, '')
    .replace(/[\s:,]+$/, '')
    .trim();
}

// BODY COPY: keep the comma behaviour, but guard against comma pile-ups.
function cleanBody(text) {
  if (!text || typeof text !== 'string') return text;
  return text
    .replace(/ — /g, ', ')
    .replace(/—/g, ', ')
    .replace(/,(\s*,)+/g, ',')
    .replace(/[ \t]+,/g, ',')
    .replace(/,\s*\./g, '.')
    .replace(/,\s*([;:!?])/g, '$1')
    .replace(/^,\s*/gm, '')
    .replace(/, {2,}/g, ', ');
}

function extractLLMText(nodeJson) {
  if (!nodeJson) return '';
  // AI Agent node outputs a string directly in .output
  if (nodeJson.output && typeof nodeJson.output === 'string') {
    return nodeJson.output;
  }
  if (nodeJson.content && Array.isArray(nodeJson.content) && nodeJson.content[0]) {
    return nodeJson.content[0].text || '';
  }
  if (nodeJson.output && nodeJson.output[0] && nodeJson.output[0].content && nodeJson.output[0].content[0]) {
    return nodeJson.output[0].content[0].text || '';
  }
  if (nodeJson.text) return nodeJson.text;
  return JSON.stringify(nodeJson);
}

function isValidUrl(str) {
  return typeof str === 'string' && str.startsWith('http');
}

function pick(a, b) {
  if (a !== undefined && a !== null && a !== '') return a;
  return (b === undefined || b === null) ? '' : b;
}

// ---- contract v2 helpers ----
function slugify(str, maxLen) {
  const limit = maxLen || 60;
  return String(str === null || str === undefined ? '' : str)
    .toLowerCase()
    .replace(/['"‘’“”]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+/, '')
    .replace(/-+$/, '')
    .slice(0, limit)
    .replace(/-+$/, '');
}

// slug must match /^[a-z0-9-]+$/, max 60 chars, no leading or trailing hyphen.
// Falls back to a slugified title when the blueprint slug is missing or unusable.
function sanitizeSlug(candidate, fallbackTitle) {
  let s = String(candidate === null || candidate === undefined ? '' : candidate)
    .trim()
    .toLowerCase()
    .replace(/^\/+/, '')
    .replace(/\/+$/, '')
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-+/, '')
    .replace(/-+$/, '')
    .slice(0, 60)
    .replace(/-+$/, '');
  if (!s || !/^[a-z0-9-]+$/.test(s)) { s = slugify(fallbackTitle, 60); }
  return s || 'tws-post';
}

// Hard-truncate at a word boundary, never mid-word.
function truncateAtWord(str, maxLen) {
  const s = String(str === null || str === undefined ? '' : str).trim();
  if (s.length <= maxLen) { return s; }
  const cut = s.slice(0, maxLen);
  const sp = cut.lastIndexOf(' ');
  return (sp > 0 ? cut.slice(0, sp) : cut).replace(/[\s,;:.\-]+$/, '').trim();
}

function normTag(t) {
  return String(t === null || t === undefined ? '' : t)
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+/, '')
    .replace(/-+$/, '');
}

function countWords(s) {
  const t = String(s === null || s === undefined ? '' : s)
    .replace(/!?\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/[#*_`>|]+/g, ' ')
    .trim();
  if (!t) { return 0; }
  const parts = t.split(/\s+/);
  let n = 0;
  for (let i = 0; i < parts.length; i++) { if (parts[i]) { n++; } }
  return n;
}

const phase2Node = $('Phase 2: SEO + Section Blueprint').first().json;
const seoRaw = extractLLMText(phase2Node);
const titleData = safeParse(seoRaw, {
  title: 'TWS Stream Recap',
  hook: '',
  seo_description: '',
  keywords: []
});

const debugInfo = [];

function getParsedBlog(nodeName, label) {
  try {
    const nodeData = $(nodeName).first().json;
    const rawText = extractLLMText(nodeData);
    const len = rawText ? rawText.length : 0;
    if (!rawText || len < 10) {
      debugInfo.push(label + ': len=' + len + ' EMPTY');
      return { ok: false, data: null };
    }
    const parsed = safeParse(rawText, null);
    const ok = !!(parsed && parsed.intro && Array.isArray(parsed.sections) && parsed.sections.length > 0);
    debugInfo.push(label + ': len=' + len + (ok ? (' OK sections=' + parsed.sections.length) : ' bad structure'));
    return { ok: ok, data: parsed };
  } catch (e) {
    debugInfo.push(label + ': ERR ' + e.message);
    return { ok: false, data: null };
  }
}

const writerParsed = getParsedBlog('Phase 4a: Ghost Writer', 'writer');
const editorParsed = getParsedBlog('Editorial Board Agent', 'editor');

let blogData = { intro: '', sections: [], conclusion: '', tags: [] };
let editorUsed = false;

if (editorParsed.ok) {
  // MERGE: editor wins on prose, writer supplies chart/image fields the editor drops.
  const ed = editorParsed.data;
  const wr = writerParsed.ok ? writerParsed.data : null;
  const writerSections = (wr && Array.isArray(wr.sections)) ? wr.sections : [];
  const mergedSections = ed.sections.map((s, idx) => {
    const w = writerSections[idx] || {};
    return {
      heading: pick(s.heading, w.heading),
      body: pick(s.body, w.body),
      keyTakeaway: pick(s.keyTakeaway, w.keyTakeaway),
      chartRef: pick(s.chartRef, w.chartRef),
      chartAlt: pick(s.chartAlt, w.chartAlt),
      imageUrl: pick(s.imageUrl, w.imageUrl),
      imageAlt: pick(s.imageAlt, w.imageAlt)
    };
  });
  blogData = {
    intro: pick(ed.intro, wr ? wr.intro : ''),
    sections: mergedSections,
    conclusion: pick(ed.conclusion, wr ? wr.conclusion : ''),
    tags: (Array.isArray(ed.tags) && ed.tags.length) ? ed.tags : ((wr && wr.tags) || []),
    faq: (Array.isArray(ed.faq) && ed.faq.length) ? ed.faq : ((wr && wr.faq) || [])
  };
  editorUsed = true;
  debugInfo.push('merge: editor+writer by index, sections=' + mergedSections.length);
} else if (writerParsed.ok) {
  // Editor JSON unusable -> fall back to the Ghost Writer draft entirely.
  blogData = writerParsed.data;
  debugInfo.push('merge: FALLBACK to ghost writer only');
}

if (!blogData.intro && (!blogData.sections || blogData.sections.length === 0)) {
  throw new Error('Blog generation failed. Debug: ' + debugInfo.join(' | '));
}

let imageData = {};
try { imageData = $('Collect Image URLs').first().json || {}; } catch (e) { imageData = {}; }
const heroImageObj = imageData.heroImage || null;
const heroImageUrl = (heroImageObj && isValidUrl(heroImageObj.url)) ? heroImageObj.url : '';
const sectionImages = Array.isArray(imageData.sectionImages) ? imageData.sectionImages : [];
const imageStats = imageData._imageStats || { total: 0, uploaded: 0, failed: 0, errors: [] };

// Get chart map from Build Chart Map node
let chartMapData = [];
try {
  chartMapData = $('Build Chart Map').first().json._chartMap || [];
} catch (e) { chartMapData = []; }

const sections = (blogData.sections || []).map((section, idx) => {
  let chartRef = isValidUrl(section.chartRef) ? section.chartRef : '';
  let chartAlt = section.chartAlt || '';

  // Priority 2: Chart map has a pre-matched chart
  if (!chartRef) {
    const mapped = chartMapData.find(c => c.sectionIndex === idx);
    if (mapped && isValidUrl(mapped.url)) {
      chartRef = mapped.url;
      chartAlt = mapped.alt_text || '';
    }
  }

  // Priority 3: Index-based from original chart_urls
  if (!chartRef && chartUrls[idx]) {
    const candidate = typeof chartUrls[idx] === 'string' ? chartUrls[idx] : (chartUrls[idx].url || '');
    if (isValidUrl(candidate)) chartRef = candidate;
  }

  // Priority 4: Generated section images
  const genImage = sectionImages.find(img => img.sectionIndex === idx) || null;
  if (!chartRef && genImage && isValidUrl(genImage.url)) {
    chartRef = genImage.url;
    if (!chartAlt && genImage.alt) chartAlt = genImage.alt;
  }

  if (!chartAlt && chartRef) chartAlt = 'Chart: ' + (section.heading || 'Section ' + (idx + 1));

  const isGen = !!(genImage && genImage.url === chartRef);

  return {
    heading: section.heading,
    body: section.body,
    keyTakeaway: section.keyTakeaway || '',
    chartRef: chartRef,
    chartAlt: chartAlt,
    chartWidth: isGen ? (genImage.width || 0) : 0,
    chartHeight: isGen ? (genImage.height || 0) : 0
  };
});

const youtubeUrl = `https://www.youtube.com/watch?v=${videoId}`;
let postTitle = cleanTitle(fixMojibake(titleData.title));
// Real YouTube video title, resolved upstream in Stage 2 (Pick Caption Credential).
// Empty when Stage 2 could not resolve it; the post title is the fallback.
const videoTitle = (typeof triggerData.video_title === 'string') ? triggerData.video_title.trim() : '';
const videoTitleOrPost = videoTitle || postTitle;
const introText = cleanBody(fixMojibake(blogData.intro));
const conclusionBase = cleanBody(fixMojibake(blogData.conclusion));

// ---------- final cleaned sections, built once so link extraction and word
// counts see exactly the text that ships ----------
const finalSections = sections.map((s, idx) => {
  const genImage = sectionImages.find(img => img.sectionIndex === idx) || null;
  return {
    heading: cleanTitle(fixMojibake(s.heading)),
    body: cleanBody(fixMojibake(s.body)),
    keyTakeaway: cleanBody(fixMojibake(s.keyTakeaway)) || '',
    chartRef: s.chartRef,
    chartAlt: s.chartAlt || '',
    chartWidth: s.chartWidth,
    chartHeight: s.chartHeight,
    // v2: object form of the generated section image, sent ALONGSIDE the legacy chart* fields
    image: (genImage && isValidUrl(genImage.url))
      ? { url: genImage.url, alt: genImage.alt || '', width: genImage.width || 0, height: genImage.height || 0 }
      : null
  };
});

// ---------- compliance block (defensive: the node may be unreachable) ----------
let compliance = { disclaimer: '', compliance_scope: '', compliance_flag: false, compliance_note: '' };
try {
  const c = $('Build Compliance Block').first().json || {};
  compliance = {
    disclaimer: (typeof c.disclaimer === 'string') ? c.disclaimer : '',
    compliance_scope: (typeof c.compliance_scope === 'string') ? c.compliance_scope : '',
    compliance_flag: c.compliance_flag === true,
    compliance_note: (typeof c.compliance_note === 'string') ? c.compliance_note : ''
  };
} catch (e) {
  debugInfo.push('compliance: unreachable');
}

// conclusion = author copy, then the YouTube line, then the disclaimer
let conclusionText = conclusionBase
  + `\n\n**Watch the full stream:** [${videoTitleOrPost} on YouTube](${youtubeUrl})`;
if (compliance.disclaimer) {
  conclusionText = conclusionText + '\n\n' + compliance.disclaimer;
}

// ---------- link extraction over the text that actually ships ----------
const sectionBlob = finalSections.map(s => s.body || '').join('\n\n');
const bodyBlob = introText + '\n\n' + sectionBlob + '\n\n' + conclusionBase;
const MD_LINK = /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g;

const internalLinks = [];
const seenInternal = {};
let mLink;
MD_LINK.lastIndex = 0;
while ((mLink = MD_LINK.exec(sectionBlob)) !== null) {
  const anchor = String(mLink[1] || '').trim();
  const url = String(mLink[2] || '').trim();
  if (url.indexOf(POST_PREFIX) !== 0) { continue; }
  if (seenInternal[url]) { continue; }
  seenInternal[url] = true;
  const path = url.split('?')[0].split('#')[0].replace(/\/+$/, '');
  const segs = path.split('/');
  internalLinks.push({ slug: segs[segs.length - 1] || '', title: anchor, url: url });
}

// ---------- external links: only citations that survived editing ----------
const externalLinks = [];
try {
  const pack = $('Build Research Pack').first().json || {};
  const cites = Array.isArray(pack.citations) ? pack.citations : [];
  const seenExt = {};
  for (let i = 0; i < cites.length; i++) {
    const c = cites[i] || {};
    const url = (typeof c.url === 'string') ? c.url.trim() : '';
    if (!url || seenExt[url]) { continue; }
    if (bodyBlob.indexOf(url) === -1) { continue; }
    seenExt[url] = true;
    externalLinks.push({ url: url, title: c.title || '', publisher: c.publisher || '' });
  }
} catch (e) {
  debugInfo.push('citations: unreachable');
}

// ---------- SEO metadata ----------
let slug = sanitizeSlug(titleData.slug, postTitle);
let seoTitle = truncateAtWord(postTitle, 60);
let primaryKeyword = (typeof titleData.primary_keyword === 'string') ? titleData.primary_keyword.trim() : '';

// ---------- stale-year guard ----------
// The model fabricates years that appear nowhere in the transcript: a July 2026 stream
// shipped as 'Effective Bitcoin Shorting Strategy for 2023 Market Turns'. Any year in
// 2000-2025 is stripped from the title, slug and primary keyword. 2026 and later are
// left untouched. The prompt-side rule is the primary fix; this is the backstop.
const STALE_YEAR_RE = /\b20(?:0\d|1\d|2[0-5])\b/;
function stripStaleYearText(str) {
  const s = String(str === null || str === undefined ? '' : str);
  if (!STALE_YEAR_RE.test(s)) { return s; }
  return s
    // drop a dangling preposition left immediately before the year
    .replace(/\s+\b(?:for|in|of|during|by)\b\s+20(?:0\d|1\d|2[0-5])\b/gi, '')
    .replace(/\b20(?:0\d|1\d|2[0-5])\b/g, '')
    .replace(/ {2,}/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/^[\s,;:.\-]+/, '')
    .replace(/[\s,;:\-]+$/, '')
    .trim();
}
