const input = query;
let allText = '';
try {
  const blog = JSON.parse(input);
  allText = [
    blog.intro || '',
    ...(blog.sections || []).map(s => s.body || ''),
    blog.conclusion || ''
  ].join('\n\n');
} catch(e) {
  allText = input;
}

const blacklisted = [
  'delve','tapestry','landscape','multifaceted','testament','pivotal',
  'crucial','comprehensive','robust','leverage','paramount','intricate',
  'nuanced','meticulous','groundbreaking','underscore','endeavor','embark',
  'synergy','transformative','innovative','cutting-edge','revolutionary',
  'harness','unlock','realm','fostering','showcasing','highlighting',
  'bolstered','garner','vibrant','commendable','enduring','utilize',
  'facilitate','subsequently','commence','additionally','moreover',
  'furthermore','notably','importantly','ultimately','fundamentally',
  'interestingly','remarkably','undoubtedly'
];

const textLower = allText.toLowerCase();
const foundBlacklisted = [];
for (const word of blacklisted) {
  const regex = new RegExp('\\b' + word + '\\b', 'gi');
  const matches = textLower.match(regex);
  if (matches) foundBlacklisted.push({ word, count: matches.length });
}

const phrases = [
  "in today's ever-evolving","it's important to note","in the realm of",
  "a testament to","at its core","let's dive in","let's delve into",
  "in conclusion","in summary","in essence","not only","paving the way",
  "when it comes to","navigate the complexities","as we explore",
  "this serves as a","a nuanced understanding"
];
const foundPhrases = [];
for (const p of phrases) {
  if (textLower.includes(p)) foundPhrases.push(p);
}

const sentences = allText.split(/[.!?]+/).filter(s => s.trim().length > 5);
const lens = sentences.map(s => s.trim().split(/\s+/).length);
let rhythmIssues = 0;
for (let i = 2; i < lens.length; i++) {
  const avg = (lens[i-2] + lens[i-1] + lens[i]) / 3;
  if (Math.abs(lens[i-2]-avg)<3 && Math.abs(lens[i-1]-avg)<3 && Math.abs(lens[i]-avg)<3) rhythmIssues++;
}

const paras = allText.split(/\n\n+/).filter(p => p.trim().length > 0);
let openerRepeats = 0;
for (let i = 1; i < paras.length; i++) {
  const prev = paras[i-1].trim().split(/\s+/)[0]?.toLowerCase();
  const curr = paras[i].trim().split(/\s+/)[0]?.toLowerCase();
  if (prev && curr && prev === curr) openerRepeats++;
}

const emDashes = (allText.match(/\u2014/g) || []).length;
const semicolons = (allText.match(/;/g) || []).length;
const wordCount = allText.split(/\s+/).filter(w => w.length > 0).length;

const bScore = Math.min(foundBlacklisted.reduce((s,b)=>s+b.count,0)*5, 30);
const pScore = Math.min(foundPhrases.length*8, 20);
const rScore = Math.min(rhythmIssues*3, 15);
const oScore = Math.min(openerRepeats*5, 15);
const emPenalty = emDashes > 8 ? Math.min((emDashes-8)*2, 8) : 0;
const aiScore = Math.min(bScore+pScore+rScore+oScore+emPenalty, 100);

return JSON.stringify({
  ai_score: aiScore,
  word_count: wordCount,
  blacklisted_words: foundBlacklisted,
  blacklisted_phrases: foundPhrases,
  rhythm_issues: rhythmIssues,
  paragraph_opener_repeats: openerRepeats,
  em_dash_count: emDashes,
  semicolon_count: semicolons,
  pass: aiScore <= 15 && foundBlacklisted.length === 0,
  summary: 'AI Score: '+aiScore+'/100 | Blacklisted: '+foundBlacklisted.reduce((s,b)=>s+b.count,0)+' words, '+foundPhrases.length+' phrases | Rhythm: '+rhythmIssues+' | Openers: '+openerRepeats+' | Em dashes: '+emDashes+' | Words: '+wordCount
});

