// Parse vision classifier output and build chart-to-section mapping
// Chart Vision Classifier is skipped entirely when there are no chart_urls,
// so referencing it must never throw.
let classifierNode = {};
try {
  const _cvc = $('Chart Vision Classifier').first();
  classifierNode = (_cvc && _cvc.json) ? _cvc.json : {};
} catch (e) { classifierNode = {}; }
const triggerData = $('Workflow Trigger').first().json;
const chartUrls = triggerData.chart_urls || [];

// Robust JSON extraction: strip code fences, then take FIRST { to LAST }.
function safeParse(str, fallback) {
  const raw = (str === null || str === undefined) ? '' : String(str);
  const stripped = raw.replace(/```[a-zA-Z0-9_-]*/g, '').trim();
  const first = stripped.indexOf('{');
  const last = stripped.lastIndexOf('}');
  const candidate = (first !== -1 && last > first) ? stripped.slice(first, last + 1) : stripped;
  try { return JSON.parse(candidate); } catch (e) {
    try { return JSON.parse(stripped); } catch (e2) {
      try { return JSON.parse(raw.trim()); } catch (e3) { return fallback; }
    }
  }
}

// Extract SEO section plan
const seoNode = $('Phase 2: SEO + Section Blueprint').first().json;
let seoRaw = '';
if (seoNode.output && seoNode.output[0] && seoNode.output[0].content && seoNode.output[0].content[0]) {
  seoRaw = seoNode.output[0].content[0].text || '';
}
const seoData = safeParse(seoRaw, { section_plan: [] });
const sections = seoData.section_plan || [];

// Extract mining data for topic matching
const miningNode = $('Phase 1: Deep Transcript Mining').first().json;
let miningRaw = '';
if (miningNode.output && miningNode.output[0] && miningNode.output[0].content && miningNode.output[0].content[0]) {
  miningRaw = miningNode.output[0].content[0].text || '';
}
const miningData = safeParse(miningRaw, { topic_clusters: [] });
const topicClusters = miningData.topic_clusters || [];

// Extract classifier results
let classifierText = '';
try {
  if (classifierNode.choices && classifierNode.choices[0]) {
    classifierText = classifierNode.choices[0].message.content || '';
  }
} catch (e) { classifierText = ''; }

const classifierData = safeParse(classifierText, { frames: [] });
const allFrames = classifierData.frames || [];

// Filter to relevant frames only (charts and screens)
const relevantFrames = allFrames.filter(f => f.is_relevant === true);

// Get total stream duration estimate from chart timestamps
const allTimestamps = chartUrls.map(c => typeof c === 'object' ? c.timestamp : 0).filter(t => t > 0);
const maxTimestamp = allTimestamps.length > 0 ? Math.max(...allTimestamps) : 3600;

// Divide stream into equal segments matching section count
const sectionCount = Math.max(sections.length, 1);
const segmentDuration = maxTimestamp / sectionCount;

// Map each relevant frame to its best-matching section
const chartMap = relevantFrames.map(frame => {
  const ts = frame.timestamp || 0;
  const segmentIndex = Math.min(Math.floor(ts / segmentDuration), sectionCount - 1);

  let bestSection = segmentIndex;
  let bestScore = 0;
  const summary = (frame.content_summary || '').toLowerCase();

  if (summary.length > 0) {
    sections.forEach((section, idx) => {
      const heading = (section.heading || '').toLowerCase();
      const angle = (section.angle || '').toLowerCase();
      const words = summary.split(/\s+/).filter(w => w.length > 3);
      let score = 0;
      words.forEach(w => {
        if (heading.includes(w)) score += 2;
        if (angle.includes(w)) score += 1;
      });
      if (idx < topicClusters.length) {
        const theme = (topicClusters[idx].theme || '').toLowerCase();
        words.forEach(w => { if (theme.includes(w)) score += 1; });
      }
      if (score > bestScore) {
        bestScore = score;
        bestSection = idx;
      }
    });
    if (bestScore < 2) bestSection = segmentIndex;
  }

  return {
    url: frame.url,
    timestamp: ts,
    classification: frame.classification,
    alt_text: frame.alt_text || '',
    content_summary: frame.content_summary || '',
    sectionIndex: Math.max(0, bestSection)
  };
});

// Deduplicate: if multiple charts map to same section, keep highest score
const sectionBestChart = {};
chartMap.forEach(chart => {
  const idx = chart.sectionIndex;
  const originalFrame = chartUrls.find(c => (typeof c === 'object' ? c.url : c) === chart.url);
  const score = originalFrame && typeof originalFrame === 'object' ? originalFrame.score : 0;
  if (!sectionBestChart[idx] || score > (sectionBestChart[idx]._score || 0)) {
    sectionBestChart[idx] = { ...chart, _score: score };
  }
});

const finalChartMap = Object.entries(sectionBestChart).map(([idx, chart]) => ({
  sectionIndex: parseInt(idx),
  url: chart.url,
  alt_text: chart.alt_text,
  content_summary: chart.content_summary,
  classification: chart.classification,
  timestamp: chart.timestamp
}));

return [{
  json: {
    _chartMap: finalChartMap,
    _chartStats: {
      total_frames: chartUrls.length,
      classified: allFrames.length,
      relevant: relevantFrames.length,
      mapped_to_sections: finalChartMap.length,
      discarded_speaker_shots: allFrames.filter(f => f.classification === 'speaker').length,
      discarded_other: allFrames.filter(f => f.classification === 'other').length
    }
  }
}];

