// Build Research Pack
// Normalises Tavily's response into { research_summary, citations[], research_ok }.
// Phase 3 runs with onError=continueRegularOutput, so this node can receive an
// error object instead of a search payload. It must NEVER throw.

const SELF_HOSTS = ['twsgurukul', 'tradingwithsidhant'];
const MAX_CITATIONS = 5;

function pack(summary, citations, ok, err) {
  const out = {
    research_summary: summary || '',
    citations: citations || [],
    research_ok: !!ok
  };
  if (!ok) {
    out.research_error = String(err === null || err === undefined ? 'unknown research error' : err).slice(0, 500);
  }
  return [{ json: out }];
}

function hostOf(url) {
  try {
    return new URL(url).hostname.toLowerCase().replace(/^www\./, '');
  } catch (e) {
    const m = String(url).match(/^https?:\/\/([^/?#]+)/i);
    return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
  }
}

let raw = {};
try {
  const first = $input.first();
  raw = (first && first.json) ? first.json : {};
} catch (e) {
  return pack('', [], false, 'no input received from Phase 3: Tavily Research');
}

try {
  // n8n surfaces node failures as an { error: ... } item under continueRegularOutput
  if (raw.error !== undefined && raw.error !== null) {
    const e = raw.error;
    let msg;
    if (typeof e === 'string') {
      msg = e;
    } else {
      msg = e.message || e.description || e.reason || JSON.stringify(e);
    }
    return pack('', [], false, 'tavily error: ' + msg);
  }

  const answer = (typeof raw.answer === 'string') ? raw.answer.trim() : '';
  if (!answer) {
    return pack('', [], false, 'tavily response contained no answer field');
  }

  const results = Array.isArray(raw.results) ? raw.results : [];
  const citations = [];
  const seen = {};

  for (let i = 0; i < results.length; i++) {
    if (citations.length >= MAX_CITATIONS) { break; }
    const r = results[i] || {};
    const url = (typeof r.url === 'string') ? r.url.trim() : '';

    // drop anything that is not a real http(s) link
    if (!/^https?:\/\//i.test(url)) { continue; }

    const host = hostOf(url);
    if (!host) { continue; }

    // never cite ourselves
    let isSelf = false;
    for (let s = 0; s < SELF_HOSTS.length; s++) {
      if (host.indexOf(SELF_HOSTS[s]) !== -1) { isSelf = true; break; }
    }
    if (isSelf) { continue; }

    if (seen[url]) { continue; }
    seen[url] = true;

    const title = (typeof r.title === 'string' && r.title.trim()) ? r.title.trim() : host;
    citations.push({ url: url, title: title, publisher: host });
  }

  return pack(answer, citations, true, null);
} catch (e) {
  return pack('', [], false, 'research pack build failed: ' + ((e && e.message) ? e.message : String(e)));
}

// Build Internal Link Pool
// Supplies the writer with real internal links so published posts stop being orphans.
// Primary source: the blog's /api/posts endpoint (node "Fetch Existing Posts").
// Fallback: sitemap.xml (node "Fetch Sitemap").
// A Code node cannot make HTTP calls, so BOTH fetches run upstream in sequence and
// are read here via $('node'). The API wins whenever it returns usable data.
// /api/posts does not exist yet and will 404 today - that is expected and handled.
// This node must NEVER throw.

const BASE = 'https://blogs.twsgurukulx.com';
const MAX_POOL = 60;

function urlFor(slug) { return BASE + '/posts/' + slug; }

function cleanSlug(s) {
  return String(s === null || s === undefined ? '' : s)
    .trim()
    .replace(/^\/+|\/+$/g, '')
    .toLowerCase();
}

// "nifty-expiry-playbook-a1b2c3d4" -> "Nifty Expiry Playbook"
function titleFromSlug(slug) {
  const stripped = String(slug || '').replace(/-[a-z0-9]{8}$/, '');
  return stripped
    .split('-')
    .filter(Boolean)
    .map(function (w) { return w.charAt(0).toUpperCase() + w.slice(1); })
    .join(' ');
}

// ---------- slug of the post currently being generated (never self-link) ----------
let currentSlug = '';
try {
  const seoNode = $('Phase 2: SEO + Section Blueprint').first().json;
  let seoRaw = '';
  if (seoNode && seoNode.output && seoNode.output[0] && seoNode.output[0].content && seoNode.output[0].content[0]) {
    seoRaw = seoNode.output[0].content[0].text || '';
  }
  const stripped = String(seoRaw).replace(/```[a-zA-Z0-9_-]*/g, '').trim();
  const a = stripped.indexOf('{');
  const b = stripped.lastIndexOf('}');
  const seo = JSON.parse(a !== -1 && b > a ? stripped.slice(a, b + 1) : stripped);
  currentSlug = cleanSlug(seo.slug);
} catch (e) {
  currentSlug = '';
}

// ---------- source 1: the posts API ----------
let apiPool = [];
try {
  const items = $('Fetch Existing Posts').all() || [];
  let list = null;

  for (let i = 0; i < items.length; i++) {
    const j = (items[i] && items[i].json) ? items[i].json : null;
    if (!j || typeof j !== 'object') { continue; }
    if (j.error !== undefined && j.error !== null) { continue; }
    if (Array.isArray(j)) { list = j; break; }
    if (Array.isArray(j.posts)) { list = j.posts; break; }
    if (Array.isArray(j.data)) { list = j.data; break; }
  }

  // n8n splits a root-level JSON array into one item per element
  if (!list) {
    const flat = [];
    for (let i = 0; i < items.length; i++) {
      const j = (items[i] && items[i].json) ? items[i].json : null;
      if (j && typeof j === 'object' && !Array.isArray(j) && j.slug && j.title) { flat.push(j); }
    }
    if (flat.length) { list = flat; }
  }

  if (Array.isArray(list)) {
    for (let i = 0; i < list.length; i++) {
      const p = list[i] || {};
      const slug = cleanSlug(p.slug);
      const title = (typeof p.title === 'string') ? p.title.trim() : '';
      if (!slug || !title) { continue; }
      apiPool.push({ slug: slug, title: title, url: urlFor(slug) });
    }
  }
} catch (e) {
  apiPool = [];
}

// ---------- source 2: sitemap.xml ----------
let sitemapPool = [];
try {
  const items = $('Fetch Sitemap').all() || [];
  let xml = '';

  for (let i = 0; i < items.length; i++) {
    const j = (items[i] && items[i].json) ? items[i].json : null;
    if (!j) { continue; }
    if (typeof j === 'string' && j.length) { xml = j; break; }
    if (typeof j.data === 'string' && j.data.length) { xml = j.data; break; }
    if (typeof j.body === 'string' && j.body.length) { xml = j.body; break; }
    if (typeof j.text === 'string' && j.text.length) { xml = j.text; break; }
  }

  if (xml && xml.indexOf('<loc') !== -1) {
    const re = /<loc>\s*([^<]+?)\s*<\/loc>/gi;
    let m;
    while ((m = re.exec(xml)) !== null) {
      if (sitemapPool.length >= MAX_POOL) { break; }
      const loc = String(m[1]).trim();
      if (loc.indexOf('/posts/') === -1) { continue; }
      if (!/^https?:\/\//i.test(loc)) { continue; }
      const path = loc.split('?')[0].split('#')[0].replace(/\/+$/, '');
      const segs = path.split('/');
      const slug = cleanSlug(segs[segs.length - 1]);
      if (!slug) { continue; }
      sitemapPool.push({ slug: slug, title: titleFromSlug(slug), url: urlFor(slug) });
    }
  }
} catch (e) {
  sitemapPool = [];
}

// ---------- pick the best source, dedupe, drop self, cap ----------
let pool = [];
let source = 'none';
if (apiPool.length > 0) {
  pool = apiPool;
  source = 'api';
} else if (sitemapPool.length > 0) {
  pool = sitemapPool;
  source = 'sitemap';
}

const seen = {};
const finalPool = [];
for (let i = 0; i < pool.length; i++) {
  const p = pool[i];
  if (!p || !p.slug || !p.title) { continue; }
  if (currentSlug && p.slug === currentSlug) { continue; }
  if (seen[p.slug]) { continue; }
  seen[p.slug] = true;
  finalPool.push(p);
  if (finalPool.length >= MAX_POOL) { break; }
}

if (finalPool.length === 0) { source = 'none'; }

return [{
  json: {
    internal_link_pool: finalPool,
    pool_size: finalPool.length,
    pool_source: source
  }
}];

// Build Compliance Block
// Reads the Phase 2 blueprint and emits the disclaimer + compliance metadata for this post.
// Sits between "Editorial Board Agent" and "Prepare Image Prompts".
// Parses the blueprint defensively (first { to last }) and must NEVER throw.

const INDIAN_DISCLAIMER = '**Disclaimer:** This article is for educational purposes only and is not investment advice. The price levels, setups and trades described are a review of market events that have already occurred, shared to illustrate a method of analysis rather than to recommend any trade. Trading With Sidhant LLP is not a SEBI-registered Investment Adviser or Research Analyst, and nothing here constitutes a recommendation to buy or sell any security. Investments in securities markets are subject to market risks; read all the related documents carefully before investing. Past performance is not indicative of future results. Please consult a SEBI-registered financial adviser before acting on any information in this article.';

const CRYPTO_DISCLAIMER = '**Disclaimer:** This article is for educational purposes only and is not investment advice. Crypto assets are unregulated in India, are highly volatile, and can lose value rapidly; there is no established investor-protection or grievance-redressal mechanism for them. Trading With Sidhant LLP is not a SEBI-registered Investment Adviser or Research Analyst, and nothing here constitutes a recommendation to buy or sell any asset. Income from virtual digital assets is taxable in India at 30% plus applicable cess, with 1% TDS on transfers. Past performance is not indicative of future results. Do your own research before trading.';

// GLOBAL = the Indian text with the SEBI market-risk sentence swapped for a generic risk sentence.
const GLOBAL_DISCLAIMER = INDIAN_DISCLAIMER.replace(
  'Investments in securities markets are subject to market risks; read all the related documents carefully before investing.',
  'All trading and investing carries risk of loss, and you should never risk capital you cannot afford to lose.'
);

const RECENT_NOTE = 'Recent Indian market data (<90 days) — post published as historical review; verify no forward-looking calls remain.';

// Robust JSON extraction: strip code fences, then take FIRST { to LAST }.
function safeParse(str, fallback) {
  const raw = (str === null || str === undefined) ? '' : String(str);
  const stripped = raw.replace(/```[a-zA-Z0-9_-]*/g, '').trim();
  const first = stripped.indexOf('{');
  const last = stripped.lastIndexOf('}');
  const candidate = (first !== -1 && last > first) ? stripped.slice(first, last + 1) : stripped;
  try { return JSON.parse(candidate); } catch (e) {
    try { return JSON.parse(stripped); } catch (e2) {
      try { return JSON.parse(raw.trim()); } catch (e3) { return fallback; }
    }
  }
}

function extractLLMText(nodeJson) {
  if (!nodeJson) return '';
  try {
    if (nodeJson.output && Array.isArray(nodeJson.output) && nodeJson.output[0] && nodeJson.output[0].content && nodeJson.output[0].content[0]) {
      return nodeJson.output[0].content[0].text || '';
    }
    if (typeof nodeJson.output === 'string') return nodeJson.output;
    if (nodeJson.content && Array.isArray(nodeJson.content) && nodeJson.content[0]) return nodeJson.content[0].text || '';
    if (typeof nodeJson.text === 'string') return nodeJson.text;
  } catch (e) { /* fall through */ }
  return '';
}

let seo = {};
try {
  seo = safeParse(extractLLMText($('Phase 2: SEO + Section Blueprint').first().json), {}) || {};
} catch (e) {
  seo = {};
}

// scope: one of indian_securities | crypto | global | mixed. Anything else falls back to global.
let scope = String(seo.market_scope === null || seo.market_scope === undefined ? '' : seo.market_scope).trim().toLowerCase();
if (['indian_securities', 'crypto', 'global', 'mixed'].indexOf(scope) === -1) { scope = 'global'; }

let ageDays = parseInt(seo.market_data_age_days, 10);
if (!isFinite(ageDays) || ageDays < 0) { ageDays = 0; }

const isIndian = (scope === 'indian_securities' || scope === 'mixed');
const complianceFlag = isIndian && ageDays < 90;

let disclaimer;
if (isIndian) {
  disclaimer = INDIAN_DISCLAIMER;
} else if (scope === 'crypto') {
  disclaimer = CRYPTO_DISCLAIMER;
} else {
  disclaimer = GLOBAL_DISCLAIMER;
}

return [{
  json: {
    disclaimer: disclaimer,
    compliance_scope: scope,
    compliance_flag: complianceFlag,
    compliance_note: complianceFlag ? RECENT_NOTE : ''
  }
}];

// CONTENT GATE — runs BEFORE any paid image generation.
// Executions 79432 and 79436 each generated and uploaded 6 images (~$0.36) and only
// then died at 'Assemble Publish Payload' with 'writer: len=54 bad structure |
// editor: len=54 bad structure'. This node moves that same verdict upstream of the spend.
//
// The extraction below is copied faithfully from 'Assemble Publish Payload'
// (safeParse + extractLLMText + the getParsedBlog validity test) so this gate and that
// node can never disagree about whether the content is usable.
//
// Pass-through: the Build Compliance Block fields are re-emitted on this item so the
// downstream item shape is unchanged. 'Assemble Publish Payload' reads
// $('Build Compliance Block') BY NAME, so it keeps resolving regardless of this node.

// Robust JSON extraction: strip code fences, then take the substring from the
// FIRST { to the LAST }. Survives LLMs that emit prose before/after the JSON.
function safeParse(str, fallback) {
  const raw = (str === null || str === undefined) ? '' : String(str);
  const stripped = raw.replace(/```[a-zA-Z0-9_-]*/g, '').trim();
  const first = stripped.indexOf('{');
  const last = stripped.lastIndexOf('}');
  const candidate = (first !== -1 && last > first) ? stripped.slice(first, last + 1) : stripped;
  try { return JSON.parse(candidate); } catch (e) {
    try { return JSON.parse(stripped); } catch (e2) {
      try { return JSON.parse(raw.trim()); } catch (e3) { return fallback; }
    }
  }
}

function extractLLMText(nodeJson) {
  if (!nodeJson) return '';
  // AI Agent node outputs a string directly in .output
  if (nodeJson.output && typeof nodeJson.output === 'string') {
    return nodeJson.output;
  }
  if (nodeJson.content && Array.isArray(nodeJson.content) && nodeJson.content[0]) {
    return nodeJson.content[0].text || '';
  }
  if (nodeJson.output && nodeJson.output[0] && nodeJson.output[0].content && nodeJson.output[0].content[0]) {
    return nodeJson.output[0].content[0].text || '';
  }
  if (nodeJson.text) return nodeJson.text;
  return JSON.stringify(nodeJson);
}

// Mirrors getParsedBlog() in 'Assemble Publish Payload': usable means a parsed object
// with a non-empty intro AND a sections array of length >= 1.
function checkOne(nodeName) {
  try {
    const nodeData = $(nodeName).first().json;
    const rawText = extractLLMText(nodeData);
    const len = rawText ? rawText.length : 0;
    if (!rawText || len < 10) { return { ok: false, len: len, why: 'EMPTY' }; }
    const parsed = safeParse(rawText, null);
    const ok = !!(parsed && parsed.intro && Array.isArray(parsed.sections) && parsed.sections.length > 0);
    return { ok: ok, len: len, why: ok ? ('OK sections=' + parsed.sections.length) : 'bad structure' };
  } catch (e) {
    return { ok: false, len: 0, why: 'ERR ' + e.message };
  }
}

const writer = checkOne('Phase 4a: Ghost Writer');
const editor = checkOne('Editorial Board Agent');

// TRUE only when at least ONE of writer/editor yields a usable object.
const contentOk = writer.ok || editor.ok;

const reason = 'writer: len=' + writer.len + ' ' + writer.why
  + ' | editor: len=' + editor.len + ' ' + editor.why;

// Pass the compliance fields through unchanged.
let compliance = {};
try { compliance = $('Build Compliance Block').first().json || {}; } catch (e) { compliance = {}; }

return [{
  json: Object.assign({}, compliance, {
    content_ok: contentOk,
    writer_len: writer.len,
    editor_len: editor.len,
    reason: reason
  })
}];

